import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container (position/rotation/scale will be applied by the adapter)
  const root = new Group();

  // Geometry – keep aspect ratio based on the source rectangle (512 × 320)
  const aspect = 512 / 320; // 1.6
  const geometry = new PlaneGeometry(aspect, 1);

  // Unlit material; texture will be assigned asynchronously
  const material = new MeshBasicNodeMaterial({ map: null, transparent: true });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load the texture synchronously (promise resolves later)
  let loadedTexture = null;
  const texPromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    })
    .catch(() => {
      // texture load failure – keep material untextured
    });

  // Store any GSAP timelines for cleanup (none in this node but keep pattern)
  const timelines = [];

  // Handlers placeholder (no interactions specified)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Dispose texture if it was loaded
    if (loadedTexture) {
      loadedTexture.dispose();
    }

    // Kill any GSAP timelines that might have been added later
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
  };

  // Apply cinematic primitives if any are declared (none for this spec)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const primitive = ctx.primitives[prim.name];
      if (primitive) {
        const result = primitive(root, prim.params ?? {});
        // keep reference for cleanup
        if (result && typeof result.cleanup === 'function') {
          timelines.push({ kill: result.cleanup });
        }
      }
    }
  }

  return root;
}
